UPDATE `creature_template` SET `npcflag`=CASE `entry` WHEN 181054 THEN 2 WHEN 181056 THEN 2 WHEN 181494 THEN 16777216 WHEN 181594 THEN 2 WHEN 181596 THEN 2 WHEN 181597 THEN 3 WHEN 182069 THEN 2 WHEN 182168 THEN 2 WHEN 183960 THEN 3 WHEN 184269 THEN 2 WHEN 192245 THEN 2 WHEN 192246 THEN 2 END, `faction`=CASE `entry` WHEN 181054 THEN 35 WHEN 181056 THEN 35 WHEN 181494 THEN 35 WHEN 181594 THEN 35 WHEN 181596 THEN 35 WHEN 181597 THEN 35 WHEN 182069 THEN 35 WHEN 182168 THEN 35 WHEN 183960 THEN 35 WHEN 184269 THEN 35 WHEN 192245 THEN 35 WHEN 192246 THEN 35 END, `AIName`=CASE `entry` WHEN 181054 THEN '' WHEN 181056 THEN '' WHEN 181494 THEN 'SmartAI' WHEN 181594 THEN '' WHEN 181596 THEN '' WHEN 181597 THEN 'SmartAI' WHEN 182069 THEN '' WHEN 182168 THEN 'SmartAI' WHEN 183960 THEN 'SmartAI' WHEN 184269 THEN 'SmartAI' WHEN 192245 THEN '' WHEN 192246 THEN '' END WHERE `entry` IN (181054,181056,181494,181594,181596,181597,182069,182168,183960,184269,192245,192246);

